struct DSHLLBindData : public FunctionData {
    DSHLLBindData() {
    }
    explicit DSHLLBindData(int32_t k) : k(k) {
    }

    unique_ptr<FunctionData> Copy() const override {
        auto copy = make_uniq<DSHLLBindData>(k);
        copy->target_type = target_type;
        return std::move(copy);
    }

    bool Equals(const FunctionData &other_p) const override {
        auto &other = other_p.Cast<DSHLLBindData>();
        return k == other.k && target_type == other.target_type;
    }

    int32_t k;
    // The register encoding of the sketches the aggregate returns.
    datasketches::target_hll_type target_type = datasketches::HLL_4;
};

unique_ptr<FunctionData> DSHLLBind(BindAggregateFunctionInput &input) {
    auto &context = input.GetClientContext();
    auto &arguments = input.GetArguments();
    auto k = DSBindConstant(context, *arguments[0], "HLL can only take a constant K value",
                            "HLL K value cannot be NULL").GetValue<int32_t>();
    if (k < 4 || k > 21) {
        throw BinderException("HLL K (lg_k) value must be between 4 and 21, got: " + std::to_string(k));
    }
    auto bind_data = make_uniq<DSHLLBindData>(k);
    // Optional trailing constant: datasketch_hll(k, data, target_type).
    if (arguments.size() == 3) {
        auto option = DSBindConstant(context, *arguments[2], "HLL target_type must be a constant",
                                     "HLL target_type cannot be NULL");
        bind_data->target_type = DSParseHLLTargetType(option.GetValue<string>());
    }
    // The constant arguments stay in the argument list (DuckDB 2.0 plan serialization and the common subplan
    // optimizer only see the arguments, not the bind data); the update callbacks read the data at index 1.
    return std::move(bind_data);
}

// Holds a union so partial states and input sketches merge into it in place.
struct DSHLLUnionState {
    datasketches::hll_union *sketch = nullptr;

    ~DSHLLUnionState() {
        delete sketch;
    }

    void CreateSketch(const DSHLLBindData &bind) {
        D_ASSERT(!sketch);
        sketch = new datasketches::hll_union(bind.k);
    }

    void CreateSketch(const DSHLLUnionState &existing) {
        if (existing.sketch) {
            sketch = new datasketches::hll_union(*existing.sketch);
        }
    }

    datasketches::hll_sketch deserialize_sketch(const string_t &data) {
        return DSDeserialize<datasketches::hll_sketch>(data, "HLL");
    }
};

static void DSHLLis_empty(DataChunk &args, ExpressionState &state, Vector &result) {
    D_ASSERT(args.ColumnCount() == 1);
    auto &sketch_vector = args.data[0];
    DSSketchCache<datasketches::hll_sketch> sketch_cache;
    UnaryExecutor::Execute<string_t, bool>(sketch_vector, result, [&](string_t sketch_data) {
        return DSGuard("datasketch_hll_is_empty", [&]() {
            const auto &sketch = sketch_cache.Get(sketch_data, "HLL");
            return sketch.is_empty();
        });
    });
}

static void DSHLLdescribe(DataChunk &args, ExpressionState &state, Vector &result) {
    D_ASSERT(args.ColumnCount() == 3);
    auto &sketch_vector = args.data[0];
    auto &summary_vector = args.data[1];
    auto &detail_vector = args.data[2];
    DSSketchCache<datasketches::hll_sketch> sketch_cache;
    TernaryExecutor::Execute<string_t, bool, bool, string_t>(sketch_vector, summary_vector, detail_vector, result, [&](string_t sketch_data, bool summary_data, bool detail_data) {
        return DSGuard("datasketch_hll_describe", [&]() {
            const auto &sketch = sketch_cache.Get(sketch_data, "HLL");
            return StringVector::AddString(result, sketch.to_string(summary_data, detail_data, false, false));
        });
    });
}

